function renderScene(m,box){S.answer=null;const g=document.createElement('div');g.className='sceneGrid';m.scenes.forEach(s=>{const b=document.createElement('button');b.className='sceneCard';b.innerHTML=`<div class="sceneArt">${sceneSVG(s.kind)}</div><div class="sceneCaption">${escapeHtml(s.caption)}</div>`;b.onclick=()=>{g.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');S.answer=s.id;setConfirm(true)};g.appendChild(b)});box.appendChild(g)}
function renderFill(m,box){S.answer=Array(m.parts.length-1).fill(null);box.innerHTML='<div class="fillWrap"><div id="sentence" class="sentence"></div><div id="wordBank" class="wordBank"></div></div>';function draw(){let h='';for(let i=0;i<S.answer.length;i++)h+=escapeHtml(m.parts[i])+`<span class="blank ${S.answer[i]?'':'empty'}" data-i="${i}">${escapeHtml(S.answer[i]||'toque para preencher')}</span>`;h+=escapeHtml(m.parts[m.parts.length-1]);$('sentence').innerHTML=h;$('sentence').querySelectorAll('.blank').forEach(b=>b.onclick=()=>{S.answer[Number(b.dataset.i)]=null;draw()});$('wordBank').innerHTML='';m.tiles.forEach(t=>{const b=document.createElement('button');b.className='word'+(S.answer.includes(t)?' used':'');b.textContent=t;b.onclick=()=>{const i=S.answer.findIndex(x=>x===null);if(i>=0){S.answer[i]=t;draw()}};$('wordBank').appendChild(b)});setConfirm(S.answer.every(Boolean))}draw()}
function renderCommunication(m,box){S.answer={};let active=null;box.innerHTML='<div class="communication"><div><div class="eyebrow" style="margin-bottom:9px">ABORDAGENS</div><div id="messagePool" class="messagePool"></div></div><div><div class="eyebrow" style="margin-bottom:9px">INTERLOCUTORES</div><div id="profileGrid" class="profileGrid"></div></div></div>';function draw(){$('messagePool').innerHTML='';m.messages.forEach(msg=>{const b=document.createElement('button');b.className=`commMsg ${active===msg.id?'active':''} ${S.answer[msg.id]?'used':''}`;b.textContent=msg.text;b.onclick=()=>{active=msg.id;draw()};$('messagePool').appendChild(b)});$('profileGrid').innerHTML='';m.profiles.forEach(p=>{const mid=Object.keys(S.answer).find(k=>S.answer[k]===p.id);const msg=m.messages.find(x=>x.id===mid);const b=document.createElement('button');b.className=`profile ${active?'target':''} ${msg?'filled':''}`;b.innerHTML=`<h4>${escapeHtml(p.name)} · ${escapeHtml(p.style)}</h4><small>${escapeHtml(p.hint)}</small><div class="drop">${msg?escapeHtml(msg.text):'Selecione uma abordagem e toque aqui.'}</div>`;b.onclick=()=>{if(!active)return;Object.keys(S.answer).forEach(k=>{if(S.answer[k]===p.id)delete S.answer[k]});S.answer[active]=p.id;active=null;draw()};$('profileGrid').appendChild(b)});setConfirm(Object.keys(S.answer).length===m.messages.length)}draw()}
function renderProcess(m,box){S.answer=Array(m.slots).fill(null);box.innerHTML='<div class="processWrap"><div id="processTrack" class="processTrack"></div><div id="cardPool" class="cardPool"></div></div>';function draw(){$('processTrack').innerHTML='';S.answer.forEach((id,i)=>{const c=m.cards.find(x=>x.id===id);const s=document.createElement('div');s.className='slot'+(id?' filled':'');s.innerHTML=c?`<strong>${i+1}.</strong><br>${escapeHtml(c.text)}`:`${i+1}. Selecione um passo`;s.onclick=()=>{S.answer[i]=null;draw()};$('processTrack').appendChild(s);if(i<S.answer.length-1){const a=document.createElement('div');a.className='arrow';a.textContent='→';$('processTrack').appendChild(a)}});$('cardPool').innerHTML='';m.cards.forEach(c=>{const b=document.createElement('button');b.className='processCard'+(S.answer.includes(c.id)?' used':'');b.textContent=c.text;b.onclick=()=>{const i=S.answer.findIndex(x=>x===null);if(i>=0){S.answer[i]=c.id;draw()}};$('cardPool').appendChild(b)});setConfirm(S.answer.every(Boolean))}draw()}
function renderStory(m,box){S.answer={};let idx=0;box.innerHTML='<div id="story" class="story"></div>';function draw(){if(idx>=m.steps.length){$('story').innerHTML='<div class="storyHead"><div class="eyebrow">CAMINHO CONSTRUÍDO</div><h3>As três decisões foram registradas.</h3><p>Confirme para receber o feedback completo desta missão.</p></div>';setConfirm(true);return}const s=m.steps[idx];$('story').innerHTML=`<div class="storyHead"><div class="eyebrow">${escapeHtml(s.title)} · ${idx+1}/${m.steps.length}</div><h3>${escapeHtml(s.text)}</h3><div class="stepMeter">${m.steps.map((_,i)=>`<span class="${i<idx?'done':i===idx?'current':''}"></span>`).join('')}</div></div><div id="storyOptions" class="storyOptions"></div>`;shuffled(s).forEach(o=>{const b=document.createElement('button');b.className='storyOption';b.textContent=o.text;b.onclick=()=>{S.answer[s.id]=o.id;idx++;draw()};$('storyOptions').appendChild(b)})}draw()}
function renderDetective(m,box){S.answer=[];const visuals=(m.reference_image&&m.altered_image)?`<div class="integrityVisualCompare"><figure><img src="${escapeHtml(m.reference_image)}" alt="Versão de referência do relatório"><figcaption>Versão de referência</figcaption></figure><figure><img src="${escapeHtml(m.altered_image)}" alt="Versão alterada do relatório"><figcaption>Versão alterada</figcaption></figure></div>`:'';box.innerHTML=`${visuals}<div class="detective"><div class="doc"><div class="docHead">Versão de referência</div><div class="docBody">${m.left.map(x=>`<div class="docLine"><span>${escapeHtml(x.field)}</span><strong>${escapeHtml(x.value)}</strong><span></span></div>`).join('')}</div></div><div class="doc"><div class="docHead">Versão alterada · selecione ${m.select_count}</div><div id="detectBody" class="docBody"></div></div></div>`;m.right.forEach(x=>{const b=document.createElement('button');b.className='detectRow';b.innerHTML=`<span>${escapeHtml(x.field)}</span><strong>${escapeHtml(x.value)}</strong><span class="mark">+</span>`;b.onclick=()=>{const i=S.answer.indexOf(x.id);if(i>=0){S.answer.splice(i,1);b.classList.remove('selected')}else if(S.answer.length<m.select_count){S.answer.push(x.id);b.classList.add('selected')}setConfirm(S.answer.length===m.select_count);$('inlineMsg').textContent=`${S.answer.length}/${m.select_count} alterações selecionadas`};$('detectBody').appendChild(b)})}
function renderCamp(m,box){S.answer={};let idx=0;box.innerHTML='<div id="campStory" class="story"></div>';function draw(){if(idx>=m.steps.length){$('campStory').innerHTML='<div class="storyHead"><div class="eyebrow">TRECHO CONCLUÍDO</div><h3>Decisões registradas.</h3><p>Confirme para concluir esta missão.</p></div>';setConfirm(true);return}const s=m.steps[idx];$('campStory').innerHTML=`<div class="storyHead"><div class="eyebrow">${escapeHtml(s.title)} · ${idx+1}/${m.steps.length}</div><h3>${escapeHtml(s.prompt)}</h3><div class="stepMeter">${m.steps.map((_,i)=>`<span class="${i<idx?'done':i===idx?'current':''}"></span>`).join('')}</div></div><div id="campOptions" class="storyOptions"></div>`;if(s.kind==='scene'){$('campOptions').classList.add('campSceneOptions');s.scenes.forEach(o=>{const b=document.createElement('button');b.className='sceneCard';b.setAttribute('aria-label',o.description||o.caption||'Cena visual');b.innerHTML=`<div class="sceneArt scenePhotoWrap">${o.asset?`<img class="scenePhoto" src="${escapeHtml(o.asset)}" alt="">`:sceneSVG(o.kind)}</div><div class="sceneCaption">${escapeHtml(o.caption||'Cena')}</div>`;b.onclick=()=>{S.answer[s.id]=o.id;idx++;draw()};$('campOptions').appendChild(b)})}else{shuffled(s).forEach(o=>{const b=document.createElement('button');b.className='storyOption';b.textContent=o.text;b.onclick=()=>{S.answer[s.id]=o.id;idx++;draw()};$('campOptions').appendChild(b)})}}draw()}


