function renderRadar(m,box){S.answer=[];box.innerHTML=`<div class="miniIntro radarIntro"><span class="miniIcon">🔎</span><div><strong>${escapeHtml(m.scene_title||'Radar')}</strong><small>Observe a imagem e selecione exatamente ${m.select_count} riscos. Há pontos que representam detalhes normais do escritório.</small></div></div><div id="radarScene" class="radarScene radarPhotoScene" role="group" aria-label="Cena de investigação visual"></div>`;const sc=$('radarScene');if(m.scene_image){sc.style.backgroundImage=`linear-gradient(180deg,rgba(5,24,40,.02),rgba(5,24,40,.12)),url('${String(m.scene_image).replace(/'/g,'')}')`}m.targets.forEach((t,idx)=>{const b=document.createElement('button');b.className='radarTarget';b.style.left=t.x+'%';b.style.top=t.y+'%';b.setAttribute('aria-label',t.label);b.innerHTML=`<span class="radarMarker">${idx+1}</span><span class="radarLabel">${escapeHtml(t.label)}</span>`;b.onclick=()=>{const i=S.answer.indexOf(t.id);if(i>=0){S.answer.splice(i,1);b.classList.remove('selected')}else if(S.answer.length<m.select_count){S.answer.push(t.id);b.classList.add('selected')}setConfirm(S.answer.length===m.select_count);$('inlineMsg').textContent=`${S.answer.length}/${m.select_count} riscos marcados`};sc.appendChild(b)});$('inlineMsg').textContent='Investigue a cena. Toque nos pontos para ver o que representam e marque somente os riscos reais.'}
function renderRoute(m,box){S.answer=null;box.innerHTML='<div class="routeGame" id="routeGame"></div>';const g=$('routeGame');m.paths.forEach((p,i)=>{const b=document.createElement('button');b.className='routeChoice';b.innerHTML=`<div class="routeChoiceHead"><span>${String.fromCharCode(65+i)}</span><strong>${escapeHtml(p.name)}</strong><small>risco ${escapeHtml(p.risk||'')}</small></div><div class="routeSteps">${p.steps.map((x,j)=>`<div><b>${j+1}</b><span>${escapeHtml(x)}</span></div>`).join('')}</div>`;b.onclick=()=>{g.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');S.answer=p.id;setConfirm(true,'ESCOLHER ESTA ROTA')};g.appendChild(b)})}
function renderMatch(m,box){S.answer={};let active=null;box.innerHTML='<div class="matchGame"><div><div class="eyebrow">SITUAÇÕES</div><div id="matchItems" class="matchItems"></div></div><div><div class="eyebrow">CONTROLES</div><div id="matchTargets" class="matchTargets"></div></div></div>';function draw(){$('matchItems').innerHTML='';m.items.forEach(it=>{const target=S.answer[it.id];const b=document.createElement('button');b.className=`matchItem ${active===it.id?'active':''} ${target?'paired':''}`;b.innerHTML=`<strong>${escapeHtml(it.text)}</strong><small>${target?'Conectado · toque para trocar':'Toque para conectar'}</small>`;b.onclick=()=>{active=it.id;draw()};$('matchItems').appendChild(b)});$('matchTargets').innerHTML='';m.targets.forEach(t=>{const used=Object.keys(S.answer).find(k=>S.answer[k]===t.id);const b=document.createElement('button');b.className=`matchTarget ${active?'target':''} ${used?'paired':''}`;b.innerHTML=`<strong>${escapeHtml(t.title)}</strong><small>${escapeHtml(t.hint||'')}</small><span>${used?'✓ conectado':'receber situação'}</span>`;b.onclick=()=>{if(!active)return;Object.keys(S.answer).forEach(k=>{if(S.answer[k]===t.id)delete S.answer[k]});S.answer[active]=t.id;active=null;draw()};$('matchTargets').appendChild(b)});setConfirm(Object.keys(S.answer).length===m.items.length,'CONCLUIR CONEXÕES')}draw()}
function renderPack(m,box){S.answer=[];box.innerHTML=`<div class="miniIntro"><span class="miniIcon">🎒</span><div><strong>Mochila de decisão</strong><small>Espaço limitado: escolha exatamente ${m.select_count} recursos.</small></div></div>${m.scene_image?`<figure class="packBoard"><img src="${escapeHtml(m.scene_image)}" alt="Mochila corporativa e recursos de apoio à decisão organizados para inspeção"><figcaption>Observe os recursos e escolha apenas o que ajuda a decidir com segurança e rastreabilidade.</figcaption></figure>`:''}<div id="packGrid" class="packGrid visualPackGrid"></div>`;const g=$('packGrid');m.items.forEach(it=>{const b=document.createElement('button');b.className='packItem visualPackItem';b.innerHTML=`${it.asset?`<img class="packThumb" src="${escapeHtml(it.asset)}" alt="">`:`<span>${escapeHtml(it.icon||'•')}</span>`}<strong>${escapeHtml(it.text)}</strong><small>ADICIONAR</small>`;b.onclick=()=>{const i=S.answer.indexOf(it.id);if(i>=0){S.answer.splice(i,1);b.classList.remove('selected')}else if(S.answer.length<m.select_count){S.answer.push(it.id);b.classList.add('selected')}g.querySelectorAll('.packItem').forEach(x=>{const small=x.querySelector('small');if(small)small.textContent=x.classList.contains('selected')?'NA MOCHILA':'ADICIONAR'});setConfirm(S.answer.length===m.select_count,'FECHAR A MOCHILA');$('inlineMsg').textContent=`${S.answer.length}/${m.select_count} recursos selecionados`};g.appendChild(b)})}


