function simulatorStateHTML(state){state=state||{integrity:75,risk:20,pressure:45,time:100};const rows=[['Integridade',state.integrity,'good'],['Risco',state.risk,'risk'],['Pressão',state.pressure,'pressure'],['Tempo',state.time,'time']];return `<div class="simGauges">${rows.map(([n,v,c])=>`<div class="simGauge ${c}"><label><span>${n}</span><b>${Math.round(Number(v||0))}</b></label><div><i style="width:${Math.max(0,Math.min(100,Number(v||0)))}%"></i></div></div>`).join('')}</div>`}
function renderSimulator(m,box){S.answer={priority:null,actions:{}};const state=m.simulator_state||S.simulatorState||{};box.innerHTML=`<div class="simulator"><div class="simTop"><div><span class="simClock">${escapeHtml(m.clock||'--:--')}</span><small>TURNO ${S.missionNo}/10 · ${escapeHtml((m.route||S.track||'').toUpperCase())}</small></div><div class="simState">${simulatorStateHTML(state)}</div></div><div class="simPriority"><div><strong>1 · PRIORIDADE</strong><span>${escapeHtml(m.priority_prompt||'O que vem primeiro?')}</span></div><div id="priorityChoices" class="priorityChoices"></div></div><div id="simQueue" class="simQueue"></div></div>`;const pc=$('priorityChoices');m.events.forEach(e=>{const b=document.createElement('button');b.textContent=e.channel||e.title;b.onclick=()=>{pc.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');S.answer.priority=e.id;simReady(m)};pc.appendChild(b)});const q=$('simQueue');m.events.forEach((e,idx)=>{const card=document.createElement('article');card.className='simEvent';card.innerHTML=`<header><span>${escapeHtml(e.channel||'DEMANDA')}</span><b>${idx+1}</b></header><h3>${escapeHtml(e.title)}</h3><div class="simActions"></div>`;const ag=card.querySelector('.simActions');shuffled(e).forEach((o,i)=>{const b=document.createElement('button');b.className='answer';b.innerHTML=`<span class="key">${String.fromCharCode(65+i)}</span>${escapeHtml(o.text)}`;b.onclick=()=>{ag.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');S.answer.actions[e.id]=o.id;simReady(m)};ag.appendChild(b)});q.appendChild(card)});simReady(m)}
function simReady(m){const n=Object.keys(S.answer.actions||{}).length,ready=Boolean(S.answer.priority)&&n===m.events.length;setConfirm(ready,'ENCERRAR ESTE TURNO');$('inlineMsg').textContent=`Prioridade ${S.answer.priority?'definida':'pendente'} · ${n}/${m.events.length} decisões registradas`}

