// B4 — Project Aurora: investigação stateful com orçamento real de ações
function auroraEvidenceMap(m){const map={};(m.revealed_evidence||[]).forEach(x=>map[x.id]=x);return map}
function auroraBudgetWarning(state,chapter){const left=Number(state.actions_left??0),used=Math.max(0,10-left),remaining=Math.max(0,11-Number(chapter||1));if(left<=0)return '<div class="auroraBudgetWarning critical"><strong>0/10 AÇÕES · O ORÇAMENTO ACABOU.</strong> Você deve terminar todos os capítulos restantes somente com as evidências já reunidas. Não haverá reposição de ações. Nos capítulos seguintes, mesmo a decisão correta fica limitada a 75% de desempenho quando faltar a evidência útil.</div>';if(chapter<=3&&used>3)return `<div class="auroraBudgetWarning"><strong>Atenção ao ritmo.</strong> Você já usou ${used}/10 ações nos capítulos iniciais. A recomendação era usar no máximo 3 e preservar recursos para o final.</div>`;if(chapter<=6&&used>6)return `<div class="auroraBudgetWarning"><strong>Atenção ao ritmo.</strong> Você já usou ${used}/10 ações antes dos capítulos finais. Preserve o que resta para as decisões do Cume.</div>`;if(left<=3&&remaining>1)return `<div class="auroraBudgetWarning"><strong>Reserve suas últimas ações.</strong> Restam ${left} ações globais para ${remaining} capítulos, incluindo o atual.</div>`;return ''}
function renderAurora(m,box,preserve=false){if(!preserve||!S.answer||typeof S.answer!=='object')S.answer={decision:null};const state=m.aurora_state||S.auroraState||{actions_left:10,risk:S.caseRisk||45,timeline_minutes:42};const revealed=auroraEvidenceMap(m),chapter=Number(m.chapter||S.missionNo||1),used=Math.max(0,10-Number(state.actions_left??10));box.innerHTML=`<div class="aurora"><div class="auroraTop"><div><span class="auroraClock">${escapeHtml(m.clock||'--:--')}</span><small>CAPÍTULO ${chapter}/10</small></div><div class="auroraCounters"><span><b>${state.actions_left??0}/10</b> AÇÕES GLOBAIS RESTANTES</span><span><b>${state.risk??S.caseRisk??0}%</b> risco do caso</span></div></div><div class="auroraBudgetGuide"><div><strong>ORÇAMENTO GLOBAL · VALE PARA TODA A ETAPA 3</strong><p>Você tem exatamente 10 ações para os 10 capítulos. Cada nova evidência consome 1 ação do mesmo orçamento e nenhuma ação volta depois. Se o contador chegar a 0, você continuará obrigatoriamente até o final sem poder investigar mais. As evidências úteis valem 25% do desempenho do capítulo. Se as ações acabarem, os capítulos seguintes sem evidência útil ficam limitados a 75%, mesmo com a decisão correta.</p></div><div class="auroraBudgetPace"><span><b>até 3</b>cap. 1–3</span><span><b>até 3</b>cap. 4–6</span><span><b>reserve 4</b>cap. 7–10</span></div></div>${auroraBudgetWarning(state,chapter)}<div class="auroraBrief"><strong>PROJECT AURORA</strong><span>Você já utilizou ${used}/10 ações globais. Investigue apenas o que pode mudar sua decisão.</span></div><div id="auroraEvidence" class="auroraEvidence"></div><div class="auroraDecision"><div class="eyebrow">DECISÃO DO CAPÍTULO</div><h3>${escapeHtml(m.decision?.prompt||'Qual é sua decisão?')}</h3><div id="auroraOptions" class="storyOptions"></div></div></div>`;const eg=$('auroraEvidence');m.investigations.forEach(e=>{const known=revealed[e.id];const b=document.createElement('article');b.className=`evidenceCard ${known?'revealed':''}`;b.innerHTML=`<header><span>${escapeHtml(e.icon||'🔎')}</span><strong>${escapeHtml(e.label)}</strong></header><p>${escapeHtml(known?known.content:e.hint||'Evidência disponível')}</p><button type="button" ${known?'':'class="secondary"'}>${known?'EVIDÊNCIA REVELADA':'INVESTIGAR · −1 AÇÃO GLOBAL'}</button>`;const bt=b.querySelector('button');if(!known){bt.disabled=Number(state.actions_left||0)<=0||Boolean(S.practiceBadge);bt.onclick=()=>investigateEvidence(e.id)}else bt.disabled=true;eg.appendChild(b)});const og=$('auroraOptions');shuffled(m.decision||{}).forEach(o=>{const b=document.createElement('button');b.className=`storyOption ${S.answer.decision===o.id?'selected':''}`;b.textContent=o.text;b.onclick=()=>{og.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');S.answer.decision=o.id;setConfirm(true,'REGISTRAR DECISÃO')};og.appendChild(b)});setConfirm(Boolean(S.answer.decision),'REGISTRAR DECISÃO');if(Number(state.actions_left||0)<=0)$('inlineMsg').textContent='0/10 AÇÕES GLOBAIS. O orçamento acabou: você deve concluir os capítulos restantes sem novas investigações. Não haverá reposição de ações; sem a evidência útil, o desempenho de cada capítulo restante fica limitado a 75%, mesmo com a decisão correta.'}
async function investigateEvidence(eid){if(S.busy)return;const m=S.mission;const state=m.aurora_state||S.auroraState||{};if(Number(state.actions_left||0)<=0)return;S.busy=true;$('inlineMsg').textContent='Investigando evidência...';try{const d=await api('/api/stage/3/investigate',{method:'POST',body:JSON.stringify({attempt_id:S.attempt,mission:S.missionNo,evidence_id:eid})});S.auroraState=d.aurora_state;m.aurora_state=d.aurora_state;m.investigated=d.investigated||[];m.revealed_evidence=m.revealed_evidence||[];if(!m.revealed_evidence.some(x=>x.id===d.evidence.id))m.revealed_evidence.push(d.evidence);S.busy=false;$('inlineMsg').textContent=`Evidência revelada · ${d.aurora_state.actions_left}/10 ações GLOBAIS restantes`;renderAurora(m,$('interaction'),true)}catch(e){S.busy=false;$('inlineMsg').textContent=e.message}}


function showAchievementQueue(items){if(window.LGCAchievement)window.LGCAchievement.show(items||[])}
function achievementInline(items){return (items||[]).map(x=>{const a=typeof x==='string'?{name:x}:x||{};return `<span class="badgeInlineAward">${a.asset?`<img src="/assets/badges/${escapeHtml(a.asset)}" alt="">`:''}${escapeHtml(a.name||'Conquista')}</span>`}).join('')}

async function submitAnswer(fromTimeout=false){if(S.busy)return;S.busy=true;clearInterval(S.timer);setConfirm(false,'SALVANDO...');$('inlineMsg').textContent=S.practiceBadge?'Validando o desafio da conquista...':'Registrando a decisão no servidor...';try{let d;if(S.practiceBadge){d=await api(`/api/practice/badge/${encodeURIComponent(S.practiceBadge)}/answer`,{method:'POST',body:JSON.stringify({mission:S.mission.content_mission||S.mission.mission,answer:S.answer,elapsed_ms:elapsedMs()})});S.practice=d.practice}else{d=await api(`/api/stage/${STAGE}/answer`,{method:'POST',body:JSON.stringify({attempt_id:S.attempt,mission:S.missionNo,answer:S.answer,elapsed_ms:elapsedMs()})});S.stageScore=d.stage_score;S.caseRisk=d.case_risk||0;S.simulatorState=d.simulator_state||S.simulatorState;S.auroraState=d.aurora_state||S.auroraState}S.lastResponse=d;showFeedback(d)}catch(e){S.busy=false;$('inlineMsg').textContent=`Não foi possível registrar: ${e.message}`;setConfirm(true,'TENTAR NOVAMENTE')}}
function timeExpired(){S.expiredNotified=true;$('inlineMsg').textContent='Tempo de referência encerrado. A missão continua aberta; a pontuação da resposta correta seguirá diminuindo até o piso de 100 pontos.'}
function showFeedback(d){const perf=Number(d.mission_result.performance||0),score=Number(d.mission_result.score||0);$('feedbackIcon').className='feedbackIcon'+(perf>=.999?'':' bad');$('feedbackIcon').textContent=perf>=.999?'✓':perf>0?'◐':'!';$('feedbackKicker').textContent=S.practiceBadge?'DESAFIO DA CONQUISTA':`MISSÃO ${S.missionNo} CONCLUÍDA`;$('feedbackTitle').textContent=perf>=.999?'Boa decisão.':perf>0?'Você acertou parte do caminho.':'Essa decisão aumentaria o risco.';$('feedbackBody').textContent=d.feedback.explain;$('bestPath').innerHTML=`<strong>MELHOR CAMINHO</strong><br>${escapeHtml(d.feedback.best)}`;$('bestPath').classList.toggle('hidden',perf>=.999);$('points').textContent=S.practiceBadge?'0 pontos · ranking preservado':`+${fmt(score)} pontos`;$('checkpoint').textContent=S.practiceBadge?'Esta tentativa vale apenas para a conquista; sua pontuação oficial não foi alterada.':checkpointText();$('badgePop').innerHTML=achievementInline(d.achievements_unlocked||d.badges_unlocked||[]);$('feedbackOverlay').classList.remove('hidden');showAchievementQueue(d.achievements_unlocked||d.badges_unlocked||[]);renderRiskMeter()}
function checkpointText(){if(STAGE===1){if(S.missionNo===5)return 'Metade da primeira subida concluída.';if(S.missionNo===8)return 'O Primeiro Acampamento já está à vista.';if(S.missionNo===10)return '🏕️ Primeiro Acampamento alcançado.';return `Checkpoint ${S.missionNo}/10 alcançado.`}if(STAGE===2){const x=S.simulatorState||{};if(S.missionNo===10)return `🏕️ Acampamento 2 alcançado · Integridade ${x.integrity??'—'} · Risco ${x.risk??'—'}.`;return `Turno ${S.missionNo}/10 encerrado · Integridade ${x.integrity??'—'} · Risco ${x.risk??'—'} · Pressão ${x.pressure??'—'}.`}const a=S.auroraState||{};if(S.missionNo===10)return `🏆 Decisão do Cume registrada · risco ${a.risk??S.caseRisk}% · ${a.actions_left??0} ações restantes.`;return `Project Aurora ${S.missionNo}/10 · risco ${a.risk??S.caseRisk}% · ${a.actions_left??0} ações de investigação restantes.`}
function continueAfterFeedback(){$('feedbackOverlay').classList.add('hidden');S.busy=false;if(S.practiceBadge){const d=S.lastResponse;if(d?.complete){finishPractice(d);return}S.missionNo=d?.practice?.next_mission||S.missionNo;loadMission();return}if(S.missionNo>=10)finishStage();else{S.missionNo++;loadMission()}}
function ensurePracticeRetryButton(){let b=$('practiceRetry');if(b)return b;b=document.createElement('button');b.id='practiceRetry';b.className='secondary';b.textContent='TENTAR NOVAMENTE AGORA';b.onclick=retryPracticeNow;$('dashboardBtn').insertAdjacentElement('afterend',b);return b}
async function retryPracticeNow(){const b=ensurePracticeRetryButton();b.disabled=true;b.textContent='REINICIANDO...';try{const d=await api(`/api/practice/badge/${encodeURIComponent(S.practiceBadge)}/start`,{method:'POST'});S.practice=d;S.missionNo=d.next_mission;S.stageScore=0;S.maxScore=0;S.lastResponse=null;$('finish').classList.add('hidden');$('game').classList.remove('hidden');b.classList.add('hidden');await countdown();await loadMission()}catch(e){b.disabled=false;b.textContent='TENTAR NOVAMENTE AGORA';$('finishError').textContent=e.message}}
function finishPractice(d){$('game').classList.add('hidden');$('finish').classList.remove('hidden');clearInterval(S.timer);$('timerText').textContent='--:--';const avg=Math.round(Number(d.practice?.average_performance||0)*100);$('finishScore').textContent='0 · ranking preservado';$('finishPerf').textContent=`${avg}%`;$('finishBadges').textContent=d.success?'1':'0';$('finishTitle').textContent=d.success?'Conquista desbloqueada!':'Ainda não desta vez.';$('finishText').textContent=d.success?`${S.practiceBadge} agora faz parte da sua jornada.`:`Você pode refazer imediatamente, sem voltar ao dashboard. Esta tentativa não alterou sua pontuação oficial.`;$('finishBadgeList').innerHTML=d.success?achievementInline(d.achievements_unlocked||[{name:S.practiceBadge}]):'';$('dashboardBtn').disabled=false;$('dashboardBtn').textContent='VOLTAR ÀS CONQUISTAS';const retry=ensurePracticeRetryButton();retry.disabled=false;retry.textContent='TENTAR NOVAMENTE AGORA';retry.classList.toggle('hidden',Boolean(d.success));$('outcome').classList.add('hidden')}
async function finishStage(){$('game').classList.add('hidden');$('finish').classList.remove('hidden');clearInterval(S.timer);$('timerText').textContent='--:--';try{const d=await api(`/api/stage/${STAGE}/complete`,{method:'POST',body:JSON.stringify({attempt_id:S.attempt})});$('finishScore').textContent=`${fmt(d.score)} / ${fmt(d.max_score)}`;$('finishPerf').textContent=`${Math.round(d.average_performance*100)}%`;$('finishBadges').textContent=String((d.participant.badges||[]).length);$('finishText').textContent=finishText(d);$('finishTitle').textContent=finishTitle();if(d.outcome){$('outcome').classList.remove('hidden');$('outcome').textContent=`Resultado do Projeto Aurora: ${d.outcome}.`}$('finishBadgeList').innerHTML='';showAchievementQueue(d.achievements_unlocked||d.badges_unlocked||[]);$('dashboardBtn').disabled=false}catch(e){$('finishText').textContent='As missões foram registradas, mas a etapa ainda não foi fechada.';$('finishError').textContent=e.message;$('retryFinish').classList.remove('hidden')}}
function finishTitle(){return STAGE===1?'Primeiro Acampamento alcançado.':STAGE===2?'Acampamento 2 alcançado.':'Cume alcançado.'}
function finishText(d){if(STAGE===1)return 'A base da jornada está concluída. Sua pontuação e conquistas já foram registradas.';if(STAGE===2)return `Seu turno ${S.track==='factory'?'Factory':'Business'} foi concluído. O estado final do simulador foi registrado e a Zona Crítica é o próximo trecho.`;return 'O Project Aurora foi concluído como um caso único. Evidências, decisões e resultado final foram registrados para sua jornada.'}
async function retryFinish(){await finishStage()}
function confirmExit(){const msg=S.practiceBadge?'Sair do desafio da conquista? Sua pontuação oficial não será alterada.':'Sair agora? As missões já salvas permanecem registradas e você poderá retomar depois.';if(confirm(msg))goDashboardSecure()}

$('startBtn').onclick=startStage;$('confirmBtn').onclick=()=>submitAnswer(false);$('feedbackContinue').onclick=continueAfterFeedback;$('exitBtn').onclick=confirmExit;$('dashboardBtn').onclick=goDashboardSecure;$('retryFinish').onclick=retryFinish;
init();
